<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>2048</title>
<style>
  * { box-sizing: border-box; }
  body {
    margin: 0;
    min-height: 100vh;
    background: #1a1a2e;
    color: #eee;
    font-family: Arial, sans-serif;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 20px;
  }
  #score { font-size: 2rem; }
  #board {
    display: grid;
    grid-template-columns: repeat(4, 100px);
    grid-template-rows: repeat(4, 100px);
    gap: 10px;
    background: #16213e;
    border-radius: 10px;
    padding: 10px;
    box-shadow: 0 0 20px rgba(0,0,0,0.5);
  }
  .cell {
    background: #0f3460;
    border-radius: 5px;
    position: relative;
  }
  .tile {
    position: absolute;
    top: 0; left: 0; right: 0; bottom: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 2.5rem;
    font-weight: bold;
    border-radius: 5px;
    transition: all 0.1s ease;
    user-select: none;
  }
  .tile-2    { background: #eee4da; color: #776e65; }
  .tile-4    { background: #ede0c8; color: #776e65; }
  .tile-8    { background: #f2b179; color: #f9f6f2; }
  .tile-16   { background: #f59563; color: #f9f6f2; }
  .tile-32   { background: #f67c5f; color: #f9f6f2; }
  .tile-64   { background: #f65e3b; color: #f9f6f2; }
  .tile-128  { background: #edcf72; color: #f9f6f2; }
  .tile-256  { background: #edcc61; color: #f9f6f2; }
  .tile-512  { background: #edc850; color: #f9f6f2; }
  .tile-1024 { background: #edc53f; color: #f9f6f2; }
  .tile-2048 { background: #edc22e; color: #f9f6f2; }
  .tile-4096,
  .tile-8192,
  .tile-16384 { background: #3c3a32; color: #f9f6f2; }
  button#reset {
    padding: 10px 20px;
    font-size: 1.2rem;
    background: #e94560;
    color: white;
    border: none;
    border-radius: 5px;
    cursor: pointer;
  }
  button#reset:hover { background: #d63a55; }
</style>
</head>
<body>
  <div id="score">Score: 0</div>
  <div id="board"></div>
  <button id="reset">New Game</button>

<script>
const Game = {
  size: 4,
  grid: [],
  score: 0,

  init() {
    this.reset();
    this.bindEvents();
  },

  bindEvents() {
    document.getElementById('reset').addEventListener('click', () => this.reset());
    window.addEventListener('keydown', (e) => {
      const map = { ArrowLeft: 'left', ArrowRight: 'right', ArrowUp: 'up', ArrowDown: 'down' };
      if (map[e.key]) {
        e.preventDefault();
        if (this.move(map[e.key])) {
          this.addRandomTile();
          this.render();
        }
      }
    });
  },

  reset() {
    this.grid = Array.from({ length: this.size }, () => Array(this.size).fill(0));
    this.score = 0;
    this.addRandomTile();
    this.addRandomTile();
    this.render();
  },

  addRandomTile() {
    const empty = [];
    for (let r = 0; r < this.size; r++) {
      for (let c = 0; c < this.size; c++) {
        if (this.grid[r][c] === 0) empty.push({ r, c });
      }
    }
    if (empty.length === 0) return;
    const { r, c } = empty[Math.floor(Math.random() * empty.length)];
    this.grid[r][c] = Math.random() < 0.9 ? 2 : 4;
  },

  move(dir) {
    const oldGrid = JSON.stringify(this.grid);
    let gainedScore = 0;

    const processLine = (line) => {
      const tiles = line.filter(v => v !== 0);
      const newLine = [];
      for (let i = 0; i < tiles.length; i++) {
        if (i + 1 < tiles.length && tiles[i] === tiles[i + 1]) {
          const merged = tiles[i] * 2;
          newLine.push(merged);
          gainedScore += merged;
          i++; // skip next tile
        } else {
          newLine.push(tiles[i]);
        }
      }
      while (newLine.length < 4) newLine.push(0);
      return newLine;
    };

    if (dir === 'left') {
      for (let r = 0; r < this.size; r++) {
        this.grid[r] = processLine(this.grid[r]);
      }
    } else if (dir === 'right') {
      for (let r = 0; r < this.size; r++) {
        const reversed = [...this.grid[r]].reverse();
        const processed = processLine(reversed);
        this.grid[r] = processed.reverse();
      }
    } else if (dir === 'up') {
      const transposed = this.transpose(this.grid);
      for (let r = 0; r < this.size; r++) {
        transposed[r] = processLine(transposed[r]);
      }
      this.grid = this.transpose(transposed);
    } else if (dir === 'down') {
      const transposed = this.transpose(this.grid);
      for (let r = 0; r < this.size; r++) {
        const reversed = [...transposed[r]].reverse();
        const processed = processLine(reversed);
        transposed[r] = processed.reverse();
      }
      this.grid = this.transpose(transposed);
    }

    if (JSON.stringify(this.grid) !== oldGrid) {
      this.score += gainedScore;
      return true;
    }
    return false;
  },

  transpose(matrix) {
    return matrix[0].map((_, i) => matrix.map(row => row[i]));
  },

  board() {
    return this.grid.map(row => [...row]);
  },

  setBoard(arr) {
    this.grid = arr.map(row => [...row]);
    this.render();
  },

  score() {
    return this.score;
  },

  render() {
    document.getElementById('score').textContent = `Score: ${this.score}`;
    const boardEl = document.getElementById('board');
    boardEl.innerHTML = '';
    for (let r = 0; r < this.size; r++) {
      for (let c = 0; c < this.size; c++) {
        const cell = document.createElement('div');
        cell.className = 'cell';
        const val = this.grid[r][c];
        if (val !== 0) {
          const tile = document.createElement('div');
          tile.className = `tile tile-${val}`;
          tile.textContent = val;
          cell.appendChild(tile);
        }
        boardEl.appendChild(cell);
      }
    }
  }
};

window.game = {
  size: Game.size,
  reset: () => Game.reset(),
  move: (dir) => Game.move(dir),
  board: () => Game.board(),
  setBoard: (arr) => Game.setBoard(arr),
  score: () => Game.score()
};

Game.init();
</script>
</body>
</html>
